const EXT = makeExt({ S, num, txt, bool, sel, col, liq, L, csv, nums, strs, tup, q, mk, rgbq, ct: s => `ct(${q(s)})`, normExpr })
export const STAMPS = [...BASE, ...MORE, ...EXT]

export const STAMP_MAP = new Map(STAMPS.map(s => [s.id, s]))

export function defaults(stamp) {
  return Object.fromEntries(stamp.props.map(pr => [pr.k, pr.def]))
}

/** Mã Typst của một mẫu với giá trị props `p` (đã điền mặc định). */
export function stampBody(stamp, p) {
  const v = { ...defaults(stamp), ...p }
  return stamp.code(v)
}

const HEAD = needs => {
  const out = ['#import "/sm-draw.typ": *']
  if (needs.has('bbt')) out.push('#import "/sang-math/bbt.typ" as sb')
  if (needs.has('geo')) out.push('#import "/sang-math/geometry.typ" as sg')
  return out.join('\n')
}

/** Tài liệu Typst chỉ chứa một mẫu (vẽ quanh gốc), có điểm "không kích thước" tại gốc để khung luôn gồm gốc. */
export function stampDocument(stamp, p, marker = false) {
  const body = stampBody(stamp, p)
  const center = stamp.k === 'content' ? `content((0, 0), ${'[#' + '{' + body + '}]'}, anchor: "center")` : body
  const needs = new Set(stamp.needs || [])
  return `${HEAD(needs)}
#sm-canvas({
  import draw: *
  circle((0, 0), radius: 0, fill: none, stroke: none)
  ${marker ? 'rect((-0.025, -0.025), (0.025, 0.025), fill: rgb("#ff00fe"), stroke: none)' : ''}
  ${center}
})`
}

/** Toàn bộ cảnh: items = [{ k, x, y, s, r, p, f }] ; W, H tính bằng cm (gốc ở góc dưới trái). */
export function sceneDocument(items, W, H, { frame = false, origin = false, marker = false } = {}) {
  const needs = new Set()
  const parts = []
  for (const it of items) {
    const st = STAMP_MAP.get(it.k)
    if (!st) continue
    ;(st.needs || []).forEach(n => needs.add(n))
    const body = stampBody(st, it.p || {})
    if (st.k === 'content') {
      parts.push(`content((${it.x}, ${it.y}), std.rotate(${it.r || 0}deg)[#std.scale(x: ${Math.round((it.s || 1) * 100) * (it.f ? -1 : 1)}%, y: ${Math.round((it.s || 1) * 100)}%)[#{${body}}]], anchor: "center")`)
    } else {
      const stmts = [`translate((${it.x}, ${it.y}))`, `rotate(${it.r || 0}deg)`, `scale(x: ${(it.s || 1) * (it.f ? -1 : 1)}, y: ${it.s || 1})`, body]
      parts.push(`group({ ${stmts.join('; ')} })`)
    }
  }
  return `${HEAD(needs)}
#sm-canvas({
  import draw: *
  ${frame ? `rect((0, 0), (${W}, ${H}), stroke: none)` : ''}
  ${origin ? 'circle((0, 0), radius: 0, fill: none, stroke: none)' : ''}
  ${marker ? 'rect((-0.025, -0.025), (0.025, 0.025), fill: rgb("#ff00fe"), stroke: none)' : ''}
  ${parts.join('\n  ')}
})`
}

/** Một mục đặt tại gốc với đúng phép xoay/tỉ lệ/lật của cảnh (để xem trước khớp bản xuất). */
export function itemDocument(it, marker = false) {
  return sceneDocument([{ ...it, x: 0, y: 0 }], 0, 0, { origin: true, marker })
}
